import{createStaffPushClient}from './staff-push-core.js';
import{staffRequest}from './staff-transport.js';
import{read,write}from './storage.js';
import{OWNER_PROJECT_URL,accountAuthClient}from './owner-auth.js';
import{initNativeSupportNotifications}from './native-support-push.js';
let client=null,userId=()=>null,roleReady=false,lastSync=0,markerTail=Promise.resolve();
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const timeout=(task,ms)=>{let timer;return Promise.race([task,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('Телефон не ответил. Повторите подключение.')),ms))]).finally(()=>clearTimeout(timer));};
async function webRegistration(){const reg=await navigator.serviceWorker.getRegistration('./')||await navigator.serviceWorker.register('./sw.js');await timeout(navigator.serviceWorker.ready,15000);return reg;}
function workerAccount(user){if(globalThis.Capacitor?.isNativePlatform?.()||!navigator.serviceWorker)return Promise.resolve();markerTail=markerTail.catch(()=>{}).then(async()=>{const reg=await navigator.serviceWorker.getRegistration('./');if(!reg?.active)return;const channel=new MessageChannel();try{await timeout(new Promise((resolve,reject)=>{channel.port1.onmessage=e=>e.data?.ok===true?resolve():reject(Error('Обновите SALAH через настройки и повторите подключение.'));reg.active.postMessage({type:'SALAH_STAFF_ACCOUNT',user:user||null},[channel.port2]);}),5000);}finally{channel.port1.close();channel.port2.close();}});return markerTail;}
function openRoom(room){if(!UUID.test(room||''))return;if(location.hash.split('?')[0]==='#staff')window.dispatchEvent(new CustomEvent('salah:staff-message-open',{detail:{room}}));else location.hash='staff?room='+room;}
function webProvider(){let prepared=null;const available=()=>{if(!globalThis.isSecureContext||!('Notification'in window)||!navigator.serviceWorker||!('PushManager'in window))throw Error('На iPhone откройте SALAH с иконки на экране «Домой».');};
 const prepare=()=>{available();return prepared??=(async()=>{const response=await fetch(OWNER_PROJECT_URL+'/functions/v1/background-reminders/config',{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Сервис уведомлений временно недоступен.');const data=await response.json(),text=data.publicKey;if(typeof text!=='string')throw Error('Не удалось подключить уведомления.');const key=Uint8Array.from(atob(text.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));if(key.length!==65||key[0]!==4)throw Error('Не удалось подключить уведомления.');return{key,reg:await webRegistration()};})().catch(error=>{prepared=null;throw error;});};
 return{prepare,async enable(){available();const permission=Notification.permission==='granted'?Promise.resolve('granted'):Notification.requestPermission();if(await permission!=='granted')throw Error('Разрешите уведомления SALAH в настройках телефона.');const{reg,key}=await prepare();const subscription=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});return{subscription:subscription.toJSON()};},async registration(){if(Notification.permission!=='granted')return null;const{reg}=await prepare(),sub=await reg.pushManager.getSubscription();return sub?{subscription:sub.toJSON()}:null;}};
}
function androidProvider(){const plugin=globalThis.Capacitor?.Plugins?.SalahSupportPush;return{async status(){if(!plugin?.enableStaff)throw Error('Обновите Android-приложение для уведомлений команды.');return plugin.getStatus();},async enable(user){const status=await this.status();if(!status.supported)throw Error('На этом устройстве недоступны уведомления Google.');await initNativeSupportNotifications()?.accountChanged();try{return await timeout(plugin.enableStaff({user}),60000);}catch(error){throw Error(error.message?.includes('notifications_denied')?'Разрешите уведомления SALAH в настройках телефона.':'Не удалось подключить уведомления. Повторите попытку.');}},registration:user=>plugin.getStaffRegistration({user}),disable:()=>plugin.disableStaff()};}
export function initStaffPush({getUserId}){if(client)return client;userId=getUserId;const platform=globalThis.Capacitor?.isNativePlatform?.()&&Capacitor.getPlatform?.()==='android'?'android':'web';client=createStaffPushClient({getUserId:userId,request:staffRequest,platform,provider:platform==='android'?androidProvider():webProvider(),readDevice:user=>read('staff-push-device:'+user,null),writeDevice:(user,id)=>write('staff-push-device:'+user,id),workerAccount});
 const sync=()=>{if(roleReady&&Date.now()-lastSync>30000){lastSync=Date.now();void client.refresh({renew:true});}};
 window.addEventListener('salah:staff-messages-ready',e=>{roleReady=!!e.detail?.actor&&e.detail.actor===userId();if(roleReady)sync();else lastSync=0;});let accountVersion=0;const bindAccount=session=>{const user=session?.user?.email_confirmed_at&&!session.user.is_anonymous?session.user.id:null;void workerAccount(user).catch(()=>{});if(!user){roleReady=false;lastSync=0;void client.refresh();}};const auth=accountAuthClient().auth;auth.onAuthStateChange((_event,session)=>{accountVersion++;setTimeout(()=>bindAccount(session),0);});const initial=accountVersion;void auth.getSession().then(({data,error})=>{if(!error&&initial===accountVersion)bindAccount(data?.session);}).catch(()=>{});window.addEventListener('online',()=>{lastSync=0;sync();});navigator.serviceWorker?.addEventListener('controllerchange',()=>{void workerAccount(userId()).catch(()=>{});lastSync=0;sync();});
 navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.user!==userId())return;if(e.data.type==='SALAH_STAFF_OPEN')openRoom(e.data.room);else if(e.data.type==='SALAH_STAFF_RECEIVED')window.dispatchEvent(new Event('salah:staff-messages-refresh'));});
 CapacitorSafeListen();function CapacitorSafeListen(){const plugin=globalThis.Capacitor?.Plugins?.SalahSupportPush;plugin?.addListener('tokenChanged',()=>{lastSync=0;sync();}).catch(()=>{});}return client;
}
export function mountStaffPushControl(host,pushClient=client){if(!host||!pushClient)return()=>{};roleReady=true;host.innerHTML='<label class="staff-push-switch"><span>Уведомления сообщений</span><input type="checkbox" role="switch" aria-label="Уведомления сообщений на этом устройстве"></label><span class="staff-push-hint" role="status"></span>';const input=host.querySelector('input'),hint=host.querySelector('[role=status]');let alive=true,busy=false,lastEnabled=false;const off=pushClient.subscribe(state=>{lastEnabled=state.enabled;if(!alive||busy)return;input.checked=state.enabled;hint.textContent=state.message||'';});input.onchange=async()=>{if(busy)return;busy=true;input.disabled=true;hint.textContent='';try{if(input.checked)await pushClient.enable();else await pushClient.disable();}catch(error){hint.textContent=error.message;input.checked=lastEnabled;}finally{busy=false;if(alive)input.disabled=false;}};void pushClient.refresh();return()=>{alive=false;input.onchange=null;off();};}
